16: const CLASSES=[{id:'guard',name:'Centinela',role:'Defensor',icon:'🛡️',color:'#7196d5',hp:138,atk:17,def:5,skill:'Muro de hierro',skillIcon:'⛨',desc:'El escudo del grupo. Aguanta golpes y protege a los débiles.',skillDesc:'Se protege y provoca a los rivales.',special:'guard'},{id:'mage',name:'Arcanista',role:'Mago',icon:'🔮',color:'#a483e6',hp:82,atk:28,def:1,skill:'Lluvia arcana',skillIcon:'✧',desc:'Canaliza energía antigua para arrasar las filas enemigas.',skillDesc:'Golpea a todos los enemigos.',special:'aoe'},{id:'ranger',name:'Exploradora',role:'Tiradora',icon:'🏹',color:'#72c89d',hp:94,atk:24,def:2,skill:'Disparo certero',skillIcon:'➶',desc:'Nunca falla. Especialista en rematar objetivos debilitados.',skillDesc:'Ataque crítico al rival más débil.',special:'snipe'},{id:'cleric',name:'Oráculo',role:'Sanadora',icon:'✨',color:'#e4c66d',hp:100,atk:15,def:2,skill:'Luz reparadora',skillIcon:'✚',desc:'La luz del alba restaura la fuerza de sus aliados.',skillDesc:'Cura a todo el equipo.',special:'heal'},{id:'rogue',name:'Sombra',role:'Asesina',icon:'🗡️',color:'#dc7c86',hp:88,atk:26,def:1,skill:'Golpe furtivo',skillIcon:'☠',desc:'Se mueve entre sombras para ejecutar golpes devastadores.',skillDesc:'Ataque doble contra un rival.',special:'double'},{id:'druid',name:'Druida',role:'Guardián',icon:'🌿',color:'#8fc875',hp:108,atk:19,def:3,skill:'Raíces vivas',skillIcon:'❋',desc:'Invoca la naturaleza para sanar y enredar a sus enemigos.',skillDesc:'Cura al aliado más herido y daña un rival.',special:'balance'},{id:'brawler',name:'Pugilista',role:'Luchador',icon:'🥊',color:'#e69b63',hp:116,atk:23,def:3,skill:'Puño sísmico',skillIcon:'✹',desc:'Un espíritu indomable y puños que hacen temblar la arena.',skillDesc:'Golpe brutal que ignora defensa.',special:'pierce'},{id:'bard',name:'Bardo',role:'Apoyo',icon:'🎵',color:'#72bfd3',hp:98,atk:17,def:2,skill:'Himno de guerra',skillIcon:'♫',desc:'Su música enciende el corazón de todos sus compañeros.',skillDesc:'Aumenta el ataque de todo... (line truncated to 2000 chars)
17: const ACCESSORIES=[{id:'amulet',name:'Amuleto solar',icon:'☀',bonus:'+18 PV',hp:18,atk:0,def:0},{id:'ring',name:'Anillo ígneo',icon:'◉',bonus:'+5 ATQ',hp:0,atk:5,def:0},{id:'boots',name:'Botas del viento',icon:'➤',bonus:'+3 ATQ · +8 PV',hp:8,atk:3,def:0},{id:'charm',name:'Talismán guardián',icon:'⬡',bonus:'+2 DEF · +8 PV',hp:8,atk:0,def:2},{id:'orb',name:'Orbe de cristal',icon:'◈',bonus:'+3 ATQ · +1 DEF',hp:0,atk:3,def:1}];const NAMES={guard:['Brann','Alda','Toren'],mage:['Iria','Vael','Mira'],ranger:['Lira','Kael','Nara'],cleric:['Elowen','Sira','Oren'],rogue:['Nyx','Vex','Rook'],druid:['Thalia','Eryn','Fen'],brawler:['Bram','Kora','Dax'],bard:['Pip','Lyra','Tavi']};let team=[],selectedId=null,enemy=[],round=1,turn='player',guarded=[],buffed=false,gameOver=false;
18: function klass(id){return CLASSES.find(c=>c.id===id)}function acc(id){return ACCESSORIES.find(a=>a.id===id)}
