function entity(u,side){const c=cls(u.classId);return {...u,side,c,maxHp:c.hp,hp:c.hp,maxMana:c.mana,mana:c.mana,atk:c.atk,def:c.def||0,acted:false,alive:true,burn:0,stun:0,buff:0,buffTurns:0,weakTurns:0}}
function startBattle(){if(team.length!==5)return;$('builderScreen').classList.add('hide');$('battleScreen').classList.add('show');document.querySelectorAll('.step')[1].classList.add('active');let used={};enemy=Array.from({length:5},(_,i)=>{const c=CLASSES[Math.floor(Math.random()*CLASSES.length)],ix=used[c.id]||0;used[c.id]=ix+1;return entity({uid:`e${i}`,classId:c.id,name:NAMES[c.id][(ix+1)%3]},'enemy')});team=team.map(u=>entity(u,'ally'));round=1;turn='player';gameOver=false;selectedId=null;targetMode=null;$('battleLog').innerHTML='';log(`¡Comienza la batalla! ${team.length} campeones contra ${enemy.length} rivales.`);renderBattle();selectAlly(team.find(x=>x.alive))}
function alive(list){return list.filter(u=>u.alive)}function front(){return alive(enemy)[0]}function lastFoe(){return alive(enemy).at(-1)}function log(text){const box=$('battleLog');box.insertAdjacentHTML('afterbegin',`<div>› ${text}</div>`);while(box.children.length>32)box.lastElementChild.remove()}
function floatText(uid,text,color){const el=document.querySelector(`[data-unit="${uid}"]`);if(!el)return;const d=document.createElement('div');d.textContent=text;d.style.cssText=`position:absolute;top:15%;left:50%;transform:translateX(-50%);z-index:9;color:${color};font:bold 12px var(--pixel);text-shadow:0 2px 3px #111`;el.appendChild(d);setTimeout(()=>d.remove(),950)}
function damage(t,amount,trueDamage=false){if(!t?.alive)return 0;const n=Math.max(0,Math.round(trueDamage?amount:amount-t.def));t.hp=Math.max(0,t.hp-n);floatText(t.uid,`−${n}`,trueDamage?'#ffbf74':'#ff8b7f');if(t.hp===0){t.alive=false;log(`${t.name} cae derrotado.`)}return n}
function strike(a,t,mult=1,opts={}){if(!t?.alive)return;const raw=(opts.flat??a.atk+a.buff)*mult;const n=damage(t,raw,opts.trueDamage);log(`${a.name} ${opts.verb||'golpea'} a ${t.name} por ${n} de daño${opts.trueDamage?' verdadero':''}.`)}
function heal(t,n){if(!t?.alive)return 0;const got=Math.min(n,t.maxHp-t.hp);t.hp+=got;if(got)floatText(t.uid,`+${got}`,'#89e0b0');return got}function restoreMana(t,n){if(!t?.alive)return 0;const got=Math.min(n,t.maxMana-t.mana);t.mana+=got;if(got)floatText(t.uid,`+${got} PM`,'#8eb6ff');return got}
function renderBattle(){for(const [list,id,side] of [[team,'allySide','ally'],[enemy,'enemySide','enemy']])$(id).innerHTML=list.map(u=>`<div class="fighter ${u.alive?'':'dead'} ${u.uid===selectedId?'active':''} ${side==='enemy'&&targetMode==='enemy'?'selected-target':''}" data-unit="${u.uid}" data-side="${side}"><div class="fighter-sprite"><img src="${makeSprite(u.c,side==='enemy')}" alt=""></div><div class="fighter-info"><div class="fighter-name">${u.name}</div><div class="hp-track"><div class="hp-fill ${u.hp/u.maxHp<.3?'low':''}" style="width:${Math.max(0,u.hp/u.maxHp*100)}%"></div></div><div class="fighter-hp">${u.hp}/${u.maxHp} · ${u.mana} PM</div><div class="status">${u.stun?'💫':u.burn?'🔥':u.buff?'⬆️':''}${u.weakTurns?' ⬇️':''}</div></div></div>`).join('');document.querySelectorAll('.fighter').forEach(el=>el.onclick=()=>{const u=[...team,...enemy].find(x=>x.uid===el.dataset.unit);if(!u?.alive||turn!=='player'||gameOver)return;if(el.dataset.side==='ally'){if(targetMode==='ally')resolveTarget(u);else if(!u.acted)selectAlly(u)}else if(targetMode==='enemy')resolveTarget(u)});const a=team.find(u=>u.uid===selectedId);$('roundPill').textContent=`RONDA ${round} · TURNO ${turn==='player'?'ALIADO':'RIVAL'}`;$('logRound').textContent=`R${round}`;$('turnBanner').textContent=gameOver?'COMBATE FINALIZADO':turn==='enemy'?'LOS RIVALES ATACAN':targetMode==='enemy'?'ELIGE UN ENEMIGO':targetMode==='ally'?'ELIGE UN ALIADO':'ELIGE UN CAMPEÓN Y SU ACCIÓN';$('activeIcon').textContent=a?a.c.icon:'⚔️';$('activeName').textContent=a?`${a.name} · ${a.c.name}`:'Elige un aliado';$('activeSub').textContent=a?`${a.hp}/${a.maxHp} PV · ${a.mana}/${a.maxMana} PM · ATQ ${a.atk+a.buff} · DEF ${a.def}`:'Pulsa un campeón vivo';$('actionButtons').innerHTML=a?a.c.actions.map((act,i)=>`<button class="action-btn" data-action="${i}" ${a.acted||turn!=='player'||a.mana<act.cost||gameOver?'disabled':''}><span class="action-icon">${act.icon}</span><span><div class="action-label">${act.name}</div><div class="action-hint">${act.hint}</div></span></button>`).join(''):'';document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>useAction(+b.dataset.action));$('actionHelp').textContent=targetMode==='enemy'?'Pulsa el enemigo que quieres seleccionar.':targetMode==='ally'?'Pulsa el aliado que quieres seleccionar.':a?`Acciones de ${a.c.name}. El maná se muestra en cada campeón.`:'Selecciona uno de tus campeones para ver sus cuatro acciones.'}
function selectAlly(u){selectedId=u?.uid||null;targetMode=null;renderBattle()}function checkEnd(){if(!alive(enemy).length){gameOver=true;showResult(true);return true}if(!alive(team).length){gameOver=true;showResult(false);return true}return false}function requestTarget(side){targetMode=side;renderBattle()}

