function selectAlly(u){selectedId=u?.uid||null;targetMode=null;pendingAction=null;renderBattle()}
function useAction(index){const u=team.find(x=>x.uid===selectedId);if(!u||u.acted||turn!=='player')return;const act=u.c.actions[index];if(!act||u.mana<act.cost)return;const targeted=['heal','grab','shoulder','sneak','stab','stun','mana'].includes(act.type);if(targeted){pendingAction=index;requestTarget(['heal','mana'].includes(act.type)?'ally':'enemy');return}executeAction(u,act,null)}
function executeAction(u,act,target){if(!u?.alive||u.acted)return;if(u.mana<act.cost){log(`${u.name} no tiene suficiente maná.`);return}u.mana-=act.cost;const foes=alive(enemy),friends=alive(team);switch(act.type){case'front':strike(u,front());break;case'pierce2':foes.slice(0,2).forEach(t=>strike(u,t,1.5,{verb:'ejecuta Corte perforante contra'}));break;case'strong':strike(u,front(),2,{verb:'descarga Golpe fuerte sobre'});break;case'warcry':friends.forEach(t=>{t.buff+=5;t.buffTurns=3});log(`${u.name} lanza un Grito de guerra: +5 ATQ para todos durante 3 turnos.`);break;case'prayer':friends.forEach(t=>heal(t,15));log(`${u.name} reza y restaura 15 PV a todo el grupo.`);break;case'heal':if(target)log(`${u.name} cura ${target.name} por ${heal(target,40)} PV.`);break;case'zone':foes.forEach(t=>{t.burn=Math.max(t.burn,2);floatText(t.uid,'🔥',' #ff9a61')});log(`${u.name} invoca una Zona sagrada. ¡Todos los enemigos arden!`);break;case'purify':friends.forEach(t=>{t.burn=0;t.stun=0;t.weakTurns=0;t.weakDebuff=0;t.buff=0;t.buffTurns=0;t.atk=cls(t.classId).atk;heal(t,10)});log(`${u.name} purifica al grupo: elimina estados y restaura 10 PV a todos.`);break;case'grab':if(target){enemy=enemy.filter(t=>t!==target);enemy.unshift(target);log(`${u.name} agarra a ${target.name} y lo arrastra hasta el frente.`)}break;case'intimidate':foes.forEach(t=>{if(!t.weakTurns){t.atk=Math.max(0,t.atk-3);t.def=Math.max(0,t.def-3);t.weakDebuff=3}t.weakTurns=3});log(`${u.name} intimida a todos: −3 ATQ y DEF durante 3 turnos.`);break;case'shoulder':if(target){strike(u,target,3,{verb:'embiste a'});const self=damage(u,u.atk+u.buff,true);log(`${u.name} recibe ${self} de daño por el impacto.`)}break;case'sneak':if(target)strike(u,target,1,{verb:'ataca furtivamente a'});break;case'stab':if(target)strike(u,target,1,{flat:15,trueDamage:true,verb:'apuñala a'});break;case'backstab':strike(u,lastFoe(),3,{verb:'ataca por la espalda a'});break;case'stun':if(target){target.stun=Math.max(target.stun,1);floatText(target.uid,'ATURDIDO','#f1cb73');log(`${u.name} soborna a ${target.name}. ¡Pierde su próximo turno!`)}break;case'mana':if(target){const got=restoreMana(target,20);log(`${u.name} esclarece a ${target.name}: +${got} PM.`)}break;case'ray':foes.slice(0,3).forEach(t=>{strike(u,t,1,{flat:15,trueDamage:true,verb:'impacta con fuego sagrado a'});t.burn=Math.max(t.burn,2)});break;case'recharge':friends.forEach(t=>restoreMana(t,50));log(`${u.name} recarga 50 PM a todos los aliados.`);break}u.acted=true;targetMode=null;pendingAction=null;renderBattle();if(checkEnd())return;if(u.hp<=0)return;if(team.every(x=>!x.alive||x.acted))setTimeout(enemyPhase,450);else selectAlly(team.find(x=>x.alive&&!x.acted))}
function resolveTarget(target){const u=team.find(x=>x.uid===selectedId),act=u?.c.actions[pendingAction];if(!u||!act||!target.alive)return;executeAction(u,act,target)}
function finishEnemyPhase(){if(checkEnd())return;round++;for(const u of [...team,...enemy]){u.acted=false;if(u.buffTurns>0&&--u.buffTurns===0)u.buff=0;if(u.weakTurns>0&&--u.weakTurns===0&&u.weakDebuff){u.atk+=u.weakDebuff;u.def+=u.weakDebuff;u.weakDebuff=0}}turn='player';targetMode=null;pendingAction=null;log(`Ronda ${round}. ¡Tu equipo toma la iniciativa!`);renderBattle();selectAlly(team.find(x=>x.alive))}
function enemyPhase(){if(gameOver)return;turn='enemy';targetMode=null;selectedId=null;renderBattle();const actors=alive(enemy).slice();let i=0;function next(){if(gameOver||checkEnd())return;if(i>=actors.length){finishEnemyPhase();return}const actor=actors[i++];if(!actor.alive){setTimeout(next,250);return}if(actor.stun){actor.stun--;log(`${actor.name} está aturdido y pierde su turno.`);renderBattle();setTimeout(next,350);return}if(actor.burn){const n=damage(actor,8,true);log(`Las llamas causan ${n} de daño a ${actor.name}.`);actor.burn--;if(checkEnd()){renderBattle();return}if(!actor.alive){renderBattle();setTimeout(next,300);return}}const live=alive(team);if(!live.length){checkEnd();return}const target=live[0];if(actor.c.id==='priest'&&Math.random()<.28){const friend=alive(enemy).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(friend){const n=heal(friend,16);log(`${actor.name} reza y cura ${n} PV a ${friend.name}.`)}}else if(actor.c.id==='mystic'&&Math.random()<.24){live.slice(0,3).forEach(t=>{const n=damage(t,9,true);log(`Un rayo de ${actor.name} inflige ${n} de daño a ${t.name}.`)})}else if(actor.c.id==='warrior'&&Math.random()<.2)strike(actor,target,1.5,{verb:'corta a'});else strike(actor,target,1+Math.random()*.2);renderBattle();if(checkEnd())return;setTimeout(next,450)}next()}
function showResult(win){$('resultSymbol').textContent=win?'🏆':'💀';$('resultTitle').textContent=win?'¡Victoria!':'Derrota';$('resultText').textContent=win?`Tu escuadrón conquistó el coliseo en ${round} ronda${round===1?'':'s'}. ¡La arena recordará sus nombres!`:'Los rivales dominaron la arena. Ajusta tu escuadrón y vuelve a luchar.';$('resultModal').classList.add('show')}
$('againBtn').onclick=()=>{$('resultModal').classList.remove('show');$('battleScreen').classList.remove('show');$('builderScreen').classList.remove('hide');document.querySelectorAll('.step')[1].classList.remove('active');team=[];enemy=[];renderTeam()};$('backBtn').onclick=()=>{if(turn==='enemy'||gameOver)return;$('battleScreen').classList.remove('show');$('builderScreen').classList.remove('hide');document.querySelectorAll('.step')[1].classList.remove('active');team=team.map(u=>({uid:u.uid,classId:u.classId,name:u.name}));renderTeam()};
